-- THQ ERP v5.2 GST & Compliance
-- Migration 233: complete authoritative GST document journal composer (validation only; no posting).
begin;
create or replace function private.gst_gl_line_v520(p_tenant_id uuid,p_mapping_key text,p_amount numeric,p_side text,p_description text,p_party_type text default null,p_party_id uuid default null) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$declare v numeric:=round(coalesce(p_amount,0),2);v_side text:=lower(trim(coalesce(p_side,'')));v_acc uuid;begin if v<0 then raise exception 'GST document journal amount cannot be negative';end if;if v=0 then return null;end if;if v_side not in('debit','credit') then raise exception 'GST document journal side must be debit or credit';end if;v_acc:=private.v4_account_id(p_tenant_id,p_mapping_key);return jsonb_strip_nulls(jsonb_build_object('account_id',v_acc,'mapping_key',p_mapping_key,'debit',case when v_side='debit' then v else 0 end,'credit',case when v_side='credit' then v else 0 end,'party_type',nullif(trim(coalesce(p_party_type,'')),''),'party_id',p_party_id,'description',p_description));end $$;
revoke all on function private.gst_gl_line_v520(uuid,text,numeric,text,text,text,uuid) from public,anon,authenticated;
create or replace function private.gst_append_nonnull_line_v520(p_lines jsonb,p_line jsonb) returns jsonb language sql immutable as $$select case when $2 is null then coalesce($1,'[]'::jsonb) else coalesce($1,'[]'::jsonb)||jsonb_build_array($2) end$$;
revoke all on function private.gst_append_nonnull_line_v520(jsonb,jsonb) from public,anon,authenticated;
create or replace function private.gst_rounding_line_v520(p_tenant_id uuid,p_delta numeric,p_orientation text,p_description text) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$declare v numeric:=round(coalesce(p_delta,0),2);o text:=lower(trim(coalesce(p_orientation,'')));begin if abs(v)<0.005 then return null;end if;if o='sale' then return private.gst_gl_line_v520(p_tenant_id,'rounding',abs(v),case when v>0 then 'credit' else 'debit' end,p_description);elsif o='purchase' then return private.gst_gl_line_v520(p_tenant_id,'rounding',abs(v),case when v>0 then 'debit' else 'credit' end,p_description);elsif o='sales_return' then return private.gst_gl_line_v520(p_tenant_id,'rounding',abs(v),case when v>0 then 'debit' else 'credit' end,p_description);elsif o='purchase_return' then return private.gst_gl_line_v520(p_tenant_id,'rounding',abs(v),case when v>0 then 'credit' else 'debit' end,p_description);else raise exception 'Unknown GST accounting rounding orientation %',p_orientation;end if;end $$;
revoke all on function private.gst_rounding_line_v520(uuid,numeric,text,text) from public,anon,authenticated;
create or replace function private.gst_snapshot_document_journal_lines_v520(p_tenant_id uuid,p_snapshot_id uuid) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$declare s public.gst_document_snapshots_v520%rowtype;v_lines jsonb:='[]'::jsonb;v_tax_lines jsonb;v_delta numeric;v_total numeric;v_paid numeric:=0;v_balance numeric;v_cost numeric:=0;v_base_stock numeric:=0;v_base_expense numeric:=0;v_party uuid;v_origin_time timestamptz;v_method record;v_payment_acc text;v_original_total numeric;v_previous_returns numeric;v_outstanding numeric;v_reduce numeric;v_credit numeric;begin select * into s from public.gst_document_snapshots_v520 where id=p_snapshot_id and tenant_id=p_tenant_id;if not found then raise exception 'Authoritative GST snapshot not found';end if;if abs(coalesce(s.additional_charges,0))>0.0001 then raise exception 'GST journal composer does not accept unclassified additional charges';end if;v_total:=round(s.grand_total,2);v_delta:=round(coalesce(s.calculation_rounding,0)+coalesce(s.round_off,0),2);v_tax_lines:=private.gst_snapshot_tax_journal_lines_v520(p_tenant_id,p_snapshot_id);
if s.source_type='sale' then select x.customer_id into v_party from public.sales x where x.id=s.source_id and x.tenant_id=p_tenant_id and x.status='posted';if v_party is null then raise exception 'Posted Sale source not found';end if;select created_at into v_origin_time from public.document_origins where tenant_id=p_tenant_id and entity_type='sale' and entity_id=s.source_id order by created_at limit 1;for v_method in select lower(coalesce(payment_method,'cash')) method,round(sum(amount),2) amount from public.sale_payments where tenant_id=p_tenant_id and sale_id=s.source_id and (v_origin_time is null or created_at<=v_origin_time) group by lower(coalesce(payment_method,'cash')) loop v_paid:=v_paid+v_method.amount;v_payment_acc:='payment.'||case when v_method.method='cash' then 'cash' when v_method.method='upi' then 'upi' when v_method.method in('card','credit_card','debit_card') then 'card' else 'bank' end;v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,v_payment_acc,v_method.amount,'debit','Sale receipt','customer',v_party));end loop;v_paid:=least(round(v_paid,2),v_total);v_balance:=round(v_total-v_paid,2);v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'accounts_receivable',v_balance,'debit','Customer receivable','customer',v_party));v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'sales_revenue',round(s.taxable_total,2),'credit','Sales revenue','customer',v_party));v_lines:=v_lines||v_tax_lines;v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_rounding_line_v520(p_tenant_id,v_delta,'sale','GST sale calculation/document round off'));select round(coalesce(sum(si.cost_total),0),2) into v_cost from public.sale_items si where si.tenant_id=p_tenant_id and si.sale_id=s.source_id;v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'cogs',v_cost,'debit','Cost of goods sold'));v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'inventory_asset',v_cost,'credit','Inventory issued'));
elsif s.source_type='purchase' then select x.supplier_id into v_party from public.purchases x where x.id=s.source_id and x.tenant_id=p_tenant_id and x.status='posted';if v_party is null then raise exception 'Posted Purchase source not found';end if;select created_at into v_origin_time from public.document_origins where tenant_id=p_tenant_id and entity_type='purchase' and entity_id=s.source_id order by created_at limit 1;select round(coalesce(sum(ls.taxable_value) filter(where p.item_type='stock'),0),2),round(coalesce(sum(ls.taxable_value) filter(where p.item_type<>'stock'),0),2) into v_base_stock,v_base_expense from public.gst_document_line_snapshots_v520 ls join public.purchase_items pi on pi.id=ls.source_line_id and pi.purchase_id=s.source_id join public.product_variants pv on pv.id=pi.variant_id join public.products p on p.id=pv.product_id where ls.snapshot_id=s.id;v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'inventory_asset',v_base_stock,'debit','Purchased stock at GST taxable value','supplier',v_party));v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'purchase_expense',v_base_expense,'debit','Purchased service/non-stock at GST taxable value','supplier',v_party));v_lines:=v_lines||v_tax_lines;v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_rounding_line_v520(p_tenant_id,v_delta,'purchase','GST purchase calculation/document round off'));for v_method in select lower(coalesce(payment_method,'cash')) method,round(sum(amount),2) amount from public.purchase_payments where tenant_id=p_tenant_id and purchase_id=s.source_id and (v_origin_time is null or created_at<=v_origin_time) group by lower(coalesce(payment_method,'cash')) loop v_paid:=v_paid+v_method.amount;v_payment_acc:='payment.'||case when v_method.method='cash' then 'cash' when v_method.method='upi' then 'upi' when v_method.method in('card','credit_card','debit_card') then 'card' else 'bank' end;v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,v_payment_acc,v_method.amount,'credit','Supplier payment','supplier',v_party));end loop;v_paid:=least(round(v_paid,2),v_total);v_balance:=round(v_total-v_paid,2);v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'accounts_payable',v_balance,'credit','Supplier payable','supplier',v_party));
elsif s.source_type='purchase_invoice_v484' then select x.supplier_id into v_party from public.purchase_invoices_v484 x where x.id=s.source_id and x.tenant_id=p_tenant_id and x.status in('draft','posted','part_paid','paid');if v_party is null then raise exception 'Purchase Invoice source not found';end if;select round(coalesce(sum(ls.taxable_value) filter(where p.item_type='stock'),0),2),round(coalesce(sum(ls.taxable_value) filter(where p.item_type<>'stock'),0),2) into v_base_stock,v_base_expense from public.gst_document_line_snapshots_v520 ls join public.purchase_invoice_items_v484 ii on ii.id=ls.source_line_id and ii.purchase_invoice_id=s.source_id join public.product_variants pv on pv.id=ii.variant_id join public.products p on p.id=pv.product_id where ls.snapshot_id=s.id;v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'inventory_asset',v_base_stock,'debit','Purchase invoice stock value','supplier',v_party));v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'purchase_expense',v_base_expense,'debit','Purchase invoice service/non-stock value','supplier',v_party));v_lines:=v_lines||v_tax_lines;v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_rounding_line_v520(p_tenant_id,v_delta,'purchase','GST purchase invoice calculation/document round off'));v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'accounts_payable',v_total,'credit','Supplier payable','supplier',v_party));
elsif s.source_type='sales_return' then select sa.customer_id,sa.grand_total into v_party,v_original_total from public.sales_returns sr join public.sales sa on sa.id=sr.sale_id and sa.tenant_id=sr.tenant_id where sr.id=s.source_id and sr.tenant_id=p_tenant_id;if v_party is null then raise exception 'Sales Return source not found';end if;select round(coalesce(sum(amount),0),2) into v_paid from public.sale_payments p join public.sales_returns sr on sr.sale_id=p.sale_id where sr.id=s.source_id;select round(coalesce(sum(r2.grand_total),0),2) into v_previous_returns from public.sales_returns r1 join public.sales_returns r2 on r2.sale_id=r1.sale_id and r2.id<>r1.id and r2.created_at<=r1.created_at and r2.refund_status<>'waived' where r1.id=s.source_id;v_outstanding:=greatest(round(v_original_total-v_paid-v_previous_returns,2),0);v_reduce:=least(v_total,v_outstanding);v_credit:=greatest(round(v_total-v_reduce,2),0);v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'sales_revenue',round(s.taxable_total,2),'debit','Sales return revenue reversal','customer',v_party));v_lines:=v_lines||v_tax_lines;v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_rounding_line_v520(p_tenant_id,v_delta,'sales_return','GST sales return calculation/document round off'));v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'accounts_receivable',v_reduce,'credit','Reduce customer receivable','customer',v_party));v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'customer_credits',v_credit,'credit','Customer return credit / refund due','customer',v_party));select round(coalesce(sum(coalesce(si.cost_total,0)*(ri.quantity/nullif(si.quantity,0))),0),2) into v_cost from public.sales_return_items ri join public.sale_items si on si.id=ri.sale_item_id where ri.sales_return_id=s.source_id;v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'inventory_asset',v_cost,'debit','Returned inventory restored'));v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'cogs',v_cost,'credit','COGS reversed for returned goods'));
elsif s.source_type='purchase_return' then select pu.supplier_id,pu.grand_total into v_party,v_original_total from public.purchase_returns pr join public.purchases pu on pu.id=pr.purchase_id and pu.tenant_id=pr.tenant_id where pr.id=s.source_id and pr.tenant_id=p_tenant_id;if v_party is null then raise exception 'Purchase Return source not found';end if;select round(coalesce(sum(amount),0),2) into v_paid from public.purchase_payments p join public.purchase_returns pr on pr.purchase_id=p.purchase_id where pr.id=s.source_id;select round(coalesce(sum(r2.grand_total),0),2) into v_previous_returns from public.purchase_returns r1 join public.purchase_returns r2 on r2.purchase_id=r1.purchase_id and r2.id<>r1.id and r2.created_at<=r1.created_at and r2.credit_status<>'waived' where r1.id=s.source_id;v_outstanding:=greatest(round(v_original_total-v_paid-v_previous_returns,2),0);v_reduce:=least(v_total,v_outstanding);v_credit:=greatest(round(v_total-v_reduce,2),0);v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'accounts_payable',v_reduce,'debit','Reduce supplier payable','supplier',v_party));v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'supplier_credits',v_credit,'debit','Supplier return credit / refund due','supplier',v_party));select round(coalesce(sum(ls.taxable_value) filter(where p.item_type='stock'),0),2),round(coalesce(sum(ls.taxable_value) filter(where p.item_type<>'stock'),0),2) into v_base_stock,v_base_expense from public.gst_document_line_snapshots_v520 ls join public.purchase_return_items ri on ri.id=ls.source_line_id and ri.purchase_return_id=s.source_id join public.product_variants pv on pv.id=ri.variant_id join public.products p on p.id=pv.product_id where ls.snapshot_id=s.id;v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'inventory_asset',v_base_stock,'credit','Purchase return stock value reversal','supplier',v_party));v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_gl_line_v520(p_tenant_id,'purchase_expense',v_base_expense,'credit','Purchase return service/non-stock reversal','supplier',v_party));v_lines:=v_lines||v_tax_lines;v_lines:=private.gst_append_nonnull_line_v520(v_lines,private.gst_rounding_line_v520(p_tenant_id,v_delta,'purchase_return','GST purchase return calculation/document round off'));else raise exception 'GST document journal composer does not support source type %',s.source_type;end if;return v_lines;end $$;
revoke all on function private.gst_snapshot_document_journal_lines_v520(uuid,uuid) from public,anon,authenticated;
create or replace function private.gst_snapshot_document_journal_validate_v520(p_tenant_id uuid,p_snapshot_id uuid) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$declare v jsonb;dr numeric;cr numeric;zero_count int;generic_gst int;begin v:=private.gst_snapshot_document_journal_lines_v520(p_tenant_id,p_snapshot_id);if jsonb_typeof(v)<>'array' or jsonb_array_length(v)<2 then raise exception 'GST document journal requires at least two lines';end if;select round(coalesce(sum((x->>'debit')::numeric),0),2),round(coalesce(sum((x->>'credit')::numeric),0),2),count(*) filter(where coalesce((x->>'debit')::numeric,0)=0 and coalesce((x->>'credit')::numeric,0)=0),count(*) filter(where x->>'mapping_key' in('input_gst','output_gst') or x->>'system_key' in('input_gst','output_gst')) into dr,cr,zero_count,generic_gst from jsonb_array_elements(v)x;if dr<=0 or cr<=0 or dr<>cr then raise exception 'GST composed journal is not balanced. Debit %, Credit %',dr,cr;end if;if zero_count>0 then raise exception 'GST composed journal contains zero-value lines';end if;if generic_gst>0 then raise exception 'GST authoritative journal must not use legacy generic Input/Output GST control lines';end if;return jsonb_build_object('valid',true,'debit',dr,'credit',cr,'line_count',jsonb_array_length(v),'lines',v);end $$;
revoke all on function private.gst_snapshot_document_journal_validate_v520(uuid,uuid) from public,anon,authenticated;
insert into public.thq_schema_releases(migration_no,schema_version,release_name,notes) values(233,'5.2.0-foundation','GST Document Journal Composer','Adds a non-posting, source-bound journal composer/validator for Sale, Purchase, Purchasing V2 Purchase Invoice, Sales Return and Purchase Return. It combines authoritative GST component lines with AR/AP/payments/revenue/inventory/direct-expense/COGS and explicit calculation+document rounding, and refuses generic GST control lines or unclassified additional charges.') on conflict(migration_no) do update set schema_version=excluded.schema_version,release_name=excluded.release_name,notes=excluded.notes;
commit;